      stderr += chunk;
    });
    child.on("error", reject);
    child.on("close", (code) => resolve({ code: code ?? -1, stdout, stderr }));
  }).catch((cause: NodeJS.ErrnoException) => {
    throw new WatcherQueryError({
      kind: "command-start",
      retryable: false,
      code: cause.code ?? null,
      detail: `Could not start ${argv[0]}: ${cause.message}`,
    });
  });
}

