async pullRequest(context: T.PrContext, observeLanding = false): Promise<T.PullRequestFacts> {
  if (observeLanding) {
    const query = `query LandingState($owner: String!, $repo: String!, $pr: Int!) {
      repository(owner: $owner, name: $repo) {
        pullRequest(number: $pr) {
          mergeable mergeStateStatus reviewDecision headRefOid headRefName baseRefName state mergedAt isDraft
          mergeQueueEntry { position }
          autoMergeRequest { enabledAt }
        }
      }
    }`;
    const value = await runJson(graphqlArgs(query, context));
    const row = record(at(value, ["data", "repository", "pullRequest"]), "pull request");
    const facts = parsePullRequest(row, context);
    if (facts.state !== "OPEN") return facts;
    if (row.mergeQueueEntry !== null) {
      const { position } = record(row.mergeQueueEntry, "pull request.mergeQueueEntry");
      if (typeof position !== "number" || !Number.isSafeInteger(position) || position < 0) missing("pull request.mergeQueueEntry.position", position);
      return { ...facts, landing: { kind: "queued", position } };
    }
    if (row.autoMergeRequest !== null) {
      const autoMerge = record(row.autoMergeRequest, "pull request.autoMergeRequest");
      return { ...facts, landing: { kind: "auto-merge-requested", enabledAt: optionalString(autoMerge.enabledAt, "pull request.autoMergeRequest.enabledAt") } };
    }
    return { ...facts, landing: { kind: "not-queued" } };
  }
  return parsePullRequest(
    await runJson([
      "gh", "pr", "view", String(context.number), "--repo", `${context.owner}/${context.repo}`, "--json",
      "mergeable,mergeStateStatus,reviewDecision,headRefOid,headRefName,baseRefName,state,mergedAt,isDraft",
    ]), context
  );
}
